sys_ui_page.client_script:
function saveChanges() {

    var propertyName = gel('propertyLabelName').value; //property Name

    var property1Value = gel('propertyValue').value;//Property Value

    alert(' property1Name ' + propertyName);
    alert(' property1Value ' + property1Value);


