sys_ui_page.processing_script:
var value = request.getParameter(property1);

try {
    var gr = new GlideRecord('incident');
    gr.initialize();
    gr.short_description = value;
    gr.insert();
    gs.info('Value From Onboarding Page ' + value);
} catch (ex) {
    gs.info('Error From Onboarding Page ' + ex);
}
